import * as THREE from 'three';

function makeCanvas(width, height, draw) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  draw(ctx, width, height);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.needsUpdate = true;
  return texture;
}

/** Soft radial glow, used for the sun and its halo. */
export function makeGlowTexture() {
  return makeCanvas(256, 256, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0.0, 'rgba(255,255,255,1)');
    g.addColorStop(0.12, 'rgba(255,248,220,0.92)');
    g.addColorStop(0.3, 'rgba(255,214,150,0.34)');
    g.addColorStop(0.58, 'rgba(255,170,110,0.09)');
    g.addColorStop(1.0, 'rgba(255,150,90,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

/** A single soft, irregular cloud puff. */
export function makeCloudTexture(seed = 1) {
  return makeCanvas(512, 256, (ctx, w, h) => {
    let s = seed * 9301 + 49297;
    const rand = () => {
      s = (s * 9301 + 49297) % 233280;
      return s / 233280;
    };

    ctx.filter = 'blur(10px)';
    const puffs = 26;
    for (let i = 0; i < puffs; i++) {
      const px = w * (0.12 + rand() * 0.76);
      const py = h * (0.4 + rand() * 0.36);
      const r = h * (0.08 + rand() * 0.2);
      const g = ctx.createRadialGradient(px, py, 0, px, py, r);
      const alpha = 0.12 + rand() * 0.2;
      g.addColorStop(0, `rgba(255,255,255,${alpha})`);
      g.addColorStop(0.55, `rgba(255,245,240,${alpha * 0.5})`);
      g.addColorStop(1, 'rgba(255,240,235,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.ellipse(px, py, r * (1.2 + rand() * 0.7), r * 0.7, 0, 0, Math.PI * 2);
      ctx.fill();
    }
    // A long, soft base so the cloud reads as a single mass.
    const base = ctx.createRadialGradient(w / 2, h * 0.66, 0, w / 2, h * 0.66, w * 0.42);
    base.addColorStop(0, 'rgba(255,250,245,0.18)');
    base.addColorStop(1, 'rgba(255,245,240,0)');
    ctx.fillStyle = base;
    ctx.beginPath();
    ctx.ellipse(w / 2, h * 0.66, w * 0.42, h * 0.14, 0, 0, Math.PI * 2);
    ctx.fill();
  });
}

/** Soft round droplet for the spray particle system. */
export function makeSprayTexture() {
  return makeCanvas(64, 64, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, 'rgba(255,255,255,1)');
    g.addColorStop(0.35, 'rgba(246,253,255,0.9)');
    g.addColorStop(0.7, 'rgba(214,244,250,0.32)');
    g.addColorStop(1, 'rgba(200,240,250,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

/** Ragged ellipse of foam that sits around the board. */
export function makeFoamRingTexture() {
  return makeCanvas(256, 512, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.save();
    ctx.translate(w / 2, h / 2);
    ctx.scale(0.55, 1);
    ctx.filter = 'blur(7px)';

    for (let i = 0; i < 140; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = 108 + Math.random() * 26;
      const x = Math.cos(a) * r;
      const y = Math.sin(a) * r;
      const rad = 3 + Math.random() * 12;
      const g = ctx.createRadialGradient(x, y, 0, x, y, rad);
      g.addColorStop(0, `rgba(255,255,255,${0.22 + Math.random() * 0.5})`);
      g.addColorStop(1, 'rgba(240,255,255,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(x, y, rad, 0, Math.PI * 2);
      ctx.fill();
    }

    // Broken, streaky ring highlights.
    for (let i = 0; i < 24; i++) {
      const a0 = Math.random() * Math.PI * 2;
      const a1 = a0 + 0.05 + Math.random() * 0.22;
      ctx.strokeStyle = `rgba(255,255,255,${0.1 + Math.random() * 0.28})`;
      ctx.lineWidth = 2 + Math.random() * 9;
      ctx.beginPath();
      ctx.arc(0, 0, 112 + Math.random() * 18, a0, a1);
      ctx.stroke();
    }
    ctx.restore();

    // A little foam dragged off the tail.
    ctx.filter = 'blur(5px)';
    for (let i = 0; i < 30; i++) {
      const x = w / 2 + (Math.random() - 0.5) * 70;
      const y = h - 50 - Math.random() * 90;
      const rad = 3 + Math.random() * 10;
      const g = ctx.createRadialGradient(x, y, 0, x, y, rad);
      g.addColorStop(0, `rgba(255,255,255,${0.1 + Math.random() * 0.3})`);
      g.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(x, y, rad, 0, Math.PI * 2);
      ctx.fill();
    }
  });
}

import * as THREE from 'three';

const RAW_WAVES = [
  { dir: [0.82, 0.57], amp: 0.58, len: 32.0, phase: 0.4, speed: 0.9 },
  { dir: [-0.38, 0.925], amp: 0.32, len: 18.0, phase: 2.2, speed: 1.05 },
  { dir: [0.97, -0.24], amp: 0.16, len: 10.5, phase: 4.1, speed: 1.15 },
  { dir: [0.15, 0.99], amp: 0.085, len: 6.6, phase: 1.1, speed: 1.3 },
];

export const WAVES = RAW_WAVES.map((w) => {
  const len = Math.hypot(w.dir[0], w.dir[1]);
  const dx = w.dir[0] / len;
  const dz = w.dir[1] / len;
  const k = (Math.PI * 2) / w.len;
  return {
    dx,
    dz,
    amp: w.amp,
    k,
    omega: w.speed * Math.sqrt(9.81 * k),
    phase: w.phase,
  };
});

const f = (n) => n.toFixed(5);

const WAVE_GLSL = `
float waveHeight(vec2 p, float t) {
  float h = 0.0;
${WAVES.map(
  (w) =>
    `  h += ${f(w.amp)} * sin(dot(vec2(${f(w.dx)}, ${f(w.dz)}), p) * ${f(w.k)} - ${f(w.omega)} * t + ${f(w.phase)});`
).join('\n')}
  return h;
}

vec2 waveGrad(vec2 p, float t) {
  vec2 g = vec2(0.0);
${WAVES.map(
  (w) =>
    `  g += ${f(w.amp * w.k)} * vec2(${f(w.dx)}, ${f(w.dz)}) * cos(dot(vec2(${f(w.dx)}, ${f(w.dz)}), p) * ${f(w.k)} - ${f(w.omega)} * t + ${f(w.phase)});`
).join('\n')}
  return g;
}
`;

/** Analytic water height and gradient, shared with the board's motion. */
export function sampleOcean(x, z, t) {
  let height = 0;
  let dx = 0;
  let dz = 0;
  for (const w of WAVES) {
    const phase = w.k * (w.dx * x + w.dz * z) - w.omega * t + w.phase;
    height += w.amp * Math.sin(phase);
    const c = w.amp * w.k * Math.cos(phase);
    dx += c * w.dx;
    dz += c * w.dz;
  }
  return { height, dx, dz };
}

const vertexShader = /* glsl */ `
uniform float uTime;
uniform vec2 uOffset;

varying vec3 vWorldPos;
varying vec3 vNormalW;
varying float vHeight;
varying vec2 vWorldXZ;

${WAVE_GLSL}

void main() {
  vec2 wxz = position.xz + uOffset;
  float h = waveHeight(wxz, uTime);
  vec2 g = waveGrad(wxz, uTime);

  vec3 worldPos = vec3(wxz.x, h, wxz.y);
  vWorldPos = worldPos;
  vNormalW = normalize(vec3(-g.x, 1.0, -g.y));
  vHeight = h;
  vWorldXZ = wxz;

  gl_Position = projectionMatrix * viewMatrix * vec4(worldPos, 1.0);
}
`;

const fragmentShader = /* glsl */ `
uniform float uTime;
uniform vec3 uSunDir;
uniform vec3 uSunColor;
uniform vec3 uDeep;
uniform vec3 uShallow;
uniform vec3 uCrest;
uniform vec3 uHorizonFog;
uniform vec3 uSkyZenith;
uniform vec3 uSkyHorizon;

varying vec3 vWorldPos;
varying vec3 vNormalW;
varying float vHeight;
varying vec2 vWorldXZ;

float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 fr = fract(p);
  fr = fr * fr * (3.0 - 2.0 * fr);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, fr.x), mix(c, d, fr.x), fr.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * vnoise(p);
    p = p * 2.03 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v;
}

void main() {
  vec3 N = normalize(vNormalW);

  // Small, shimmering ripples on top of the long swell.
  vec2 q = vWorldXZ * 0.5 + vec2(uTime * 0.16, -uTime * 0.11);
  float e = 0.09;
  float n0 = fbm(q);
  float nx = fbm(q + vec2(e, 0.0));
  float nz = fbm(q + vec2(0.0, e));
  N = normalize(N + vec3(-(nx - n0), 0.0, -(nz - n0)) * 1.6);

  vec3 V = normalize(cameraPosition - vWorldPos);
  vec3 L = normalize(uSunDir);
  vec3 R = reflect(-V, N);

  float fresnel = 0.02 + 0.98 * pow(1.0 - max(dot(N, V), 0.0), 5.0);
  fresnel = clamp(fresnel * 1.15, 0.0, 1.0);

  // Water body colour, warming as the swell rises toward the light.
  float depthMix = smoothstep(-0.75, 0.9, vHeight);
  vec3 base = mix(uDeep, uShallow, depthMix);
  float scatter = pow(max(dot(N, L), 0.0), 3.0) * smoothstep(-0.1, 0.9, vHeight);
  base += uCrest * scatter * 0.22;

  // Reflected sunset.
  vec3 skyRef = mix(uSkyHorizon, uSkyZenith, smoothstep(-0.04, 0.62, R.y));
  skyRef = mix(skyRef, vec3(1.0, 0.67, 0.4), exp(-max(R.y, 0.0) * 7.0) * 0.3);
  float sunAlign = max(dot(R, L), 0.0);
  skyRef += uSunColor * pow(sunAlign, 10.0) * 0.55;

  float spec = pow(sunAlign, 340.0) * 5.0 + pow(sunAlign, 70.0) * 0.35;
  float sparkle = smoothstep(0.5, 0.95, vnoise(vWorldXZ * 6.5 + vec2(uTime * 1.6, -uTime * 1.25)));
  spec *= 0.5 + 1.1 * sparkle;

  vec3 col = mix(base, skyRef, fresnel * 0.8);
  col += uSunColor * spec;

  // Whitecaps and thin foam streaks.
  float foamNoise = fbm(vWorldXZ * 0.65 + vec2(uTime * 0.06, -uTime * 0.04));
  float crest = smoothstep(0.38, 0.92, vHeight + (foamNoise - 0.5) * 0.55);
  float streak = smoothstep(0.32, 0.82, fbm(vWorldXZ * 1.7 + vec2(0.0, uTime * 0.16)));
  float foam = crest * (0.18 + 0.82 * streak);
  foam += smoothstep(0.83, 0.98, streak) * smoothstep(0.0, 0.55, vHeight) * 0.28;
  foam = clamp(foam, 0.0, 1.0);
  col = mix(col, vec3(0.93, 0.985, 0.98), foam * 0.78);

  // Aerial haze toward the horizon.
  float dist = length(cameraPosition - vWorldPos);
  float fogF = 1.0 - exp(-dist * 0.0052);
  fogF = clamp(fogF, 0.0, 1.0);
  col = mix(col, uHorizonFog, fogF);

  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createOcean() {
  const size = 700;
  const segments = 420;
  const geometry = new THREE.PlaneGeometry(size, size, segments, segments);
  geometry.rotateX(-Math.PI / 2);

  const uniforms = {
    uTime: { value: 0 },
    uOffset: { value: new THREE.Vector2() },
    uSunDir: { value: new THREE.Vector3(0.62, 0.13, -0.78).normalize() },
    uSunColor: { value: new THREE.Color(0xffd7a0) },
    uDeep: { value: new THREE.Color(0x073846) },
    uShallow: { value: new THREE.Color(0x0e6d72) },
    uCrest: { value: new THREE.Color(0x7fd7c4) },
    uHorizonFog: { value: new THREE.Color(0xf3bf96) },
    uSkyZenith: { value: new THREE.Color(0x274d78) },
    uSkyHorizon: { value: new THREE.Color(0xffc38d) },
  };

  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader,
    fragmentShader,
    side: THREE.FrontSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  mesh.renderOrder = -1;

  const cell = size / segments;

  return {
    mesh,
    uniforms,
    update(time, focus) {
      uniforms.uTime.value = time;
      mesh.position.x = Math.round(focus.x / cell) * cell;
      mesh.position.z = Math.round(focus.z / cell) * cell;
      uniforms.uOffset.value.set(mesh.position.x, mesh.position.z);
    },
  };
}

import * as THREE from 'three';
import { makeCloudTexture, makeGlowTexture } from './textures.js';

export const SUN_DIR = new THREE.Vector3(-0.74, 0.125, -0.66).normalize();

const skyVertex = /* glsl */ `
varying vec3 vDir;

void main() {
  vDir = normalize(position);
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
}
`;

const skyFragment = /* glsl */ `
uniform vec3 uSunDir;
uniform vec3 uZenith;
uniform vec3 uMid;
uniform vec3 uHorizon;
uniform vec3 uSunColor;

varying vec3 vDir;

void main() {
  vec3 dir = normalize(vDir);
  float h = dir.y;

  vec3 col = mix(uHorizon, uMid, smoothstep(-0.01, 0.23, h));
  col = mix(col, uZenith, smoothstep(0.16, 0.72, h));

  float d = max(dot(dir, normalize(uSunDir)), 0.0);

  // Broad sunset bloom around the sun.
  col += uSunColor * pow(d, 220.0) * 1.35;
  col += vec3(1.0, 0.55, 0.3) * pow(d, 18.0) * 0.22;
  col += vec3(1.0, 0.42, 0.25) * pow(d, 4.0) * 0.055;

  // Thin, luminous haze sitting on the horizon.
  float haze = exp(-max(h, 0.0) * 22.0);
  col = mix(col, vec3(1.0, 0.76, 0.55), haze * 0.35);

  // Sun disc.
  float disc = smoothstep(0.99955, 0.99982, d);
  col = mix(col, vec3(1.0, 0.95, 0.78), disc);

  // Darken the tiny sliver below the horizon.
  col = mix(vec3(0.12, 0.17, 0.2), col, smoothstep(-0.09, 0.015, h));

  // Dither to keep the long gradient clean.
  float dither = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453);
  col += (dither - 0.5) / 255.0;

  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

function makeBird(scale, flapSpeed, phase) {
  const bird = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({
    color: 0x22303c,
    side: THREE.DoubleSide,
    transparent: true,
    opacity: 0.82,
  });

  const wingGeom = new THREE.BufferGeometry();
  wingGeom.setAttribute(
    'position',
    new THREE.Float32BufferAttribute(
      [0, 0, 0.06, 0.95, 0.12, 0, 0.3, 0.02, -0.2],
      3
    )
  );
  wingGeom.computeVertexNormals();

  const right = new THREE.Mesh(wingGeom, mat);
  const left = new THREE.Mesh(wingGeom, mat);
  left.scale.x = -1;

  const rightPivot = new THREE.Group();
  rightPivot.add(right);
  const leftPivot = new THREE.Group();
  leftPivot.add(left);
  bird.add(rightPivot, leftPivot);

  bird.scale.setScalar(scale);
  bird.userData = { rightPivot, leftPivot, flapSpeed, phase };
  return bird;
}

export function createSky() {
  const group = new THREE.Group();

  const skyUniforms = {
    uSunDir: { value: SUN_DIR.clone() },
    uZenith: { value: new THREE.Color(0x1a345e) },
    uMid: { value: new THREE.Color(0x8d6c96) },
    uHorizon: { value: new THREE.Color(0xffc68f) },
    uSunColor: { value: new THREE.Color(0xffdca0) },
  };

  const dome = new THREE.Mesh(
    new THREE.SphereGeometry(1300, 48, 24),
    new THREE.ShaderMaterial({
      uniforms: skyUniforms,
      vertexShader: skyVertex,
      fragmentShader: skyFragment,
      side: THREE.BackSide,
      depthWrite: false,
    })
  );
  dome.renderOrder = -10;
  group.add(dome);

  const glowTexture = makeGlowTexture();

  const halo = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: glowTexture,
      color: 0xffc47a,
      transparent: true,
      opacity: 0.5,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
  );
  halo.position.copy(SUN_DIR).multiplyScalar(980);
  halo.scale.setScalar(360);
  group.add(halo);

  const core = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: glowTexture,
      color: 0xfff1c8,
      transparent: true,
      opacity: 0.95,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
  );
  core.position.copy(SUN_DIR).multiplyScalar(960);
  core.scale.setScalar(66);
  group.add(core);

  // Deterministic cloud layout.
  let seed = 7;
  const rand = () => {
    seed = (seed * 16807) % 2147483647;
    return (seed - 1) / 2147483646;
  };

  const cloudTextures = [makeCloudTexture(3), makeCloudTexture(11), makeCloudTexture(23)];
  const tints = [0xffc3a4, 0xf0aeb4, 0xd9b0cc, 0xffd6b0, 0xc9a9c9];
  const sunAz = Math.atan2(SUN_DIR.x, SUN_DIR.z);

  for (let i = 0; i < 10; i++) {
    const az = sunAz + (rand() - 0.5) * 2.1;
    const dist = 720 + rand() * 210;
    const y = 28 + rand() * 175;
    const sprite = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: cloudTextures[i % cloudTextures.length],
        color: tints[i % tints.length],
        transparent: true,
        opacity: 0.22 + rand() * 0.3,
        depthWrite: false,
      })
    );
    sprite.position.set(Math.sin(az) * dist, y, Math.cos(az) * dist);
    const s = 120 + rand() * 170;
    sprite.scale.set(s * (1.4 + rand() * 0.5), s * (0.55 + rand() * 0.25), 1);
    sprite.material.rotation = (rand() - 0.5) * 0.35;
    group.add(sprite);
  }

  // A few distant birds, small enough to read as silhouettes.
  const birds = [];
  const birdData = [
    [-120, 62, -240, 2.1, 1.25, 0.0],
    [-62, 88, -300, 1.7, 0.95, 1.7],
    [58, 52, -265, 1.5, 1.45, 3.1],
    [130, 96, -310, 1.9, 1.1, 4.4],
    [-185, 38, -205, 1.4, 1.6, 2.4],
  ];
  for (const [x, y, z, s, speed, phase] of birdData) {
    const bird = makeBird(s, speed, phase);
    bird.position.set(x, y, z);
    group.add(bird);
    birds.push(bird);
  }

  return {
    group,
    update(time, camera) {
      group.position.copy(camera.position);
      for (const bird of birds) {
        const { rightPivot, leftPivot, flapSpeed, phase } = bird.userData;
        const flap = Math.sin(time * flapSpeed + phase) * 0.55;
        rightPivot.rotation.z = flap;
        leftPivot.rotation.z = -flap;
        bird.position.x += Math.sin(time * 0.05 + phase) * 0.0015;
      }
    },
  };
}

import * as THREE from 'three';
import { sampleOcean } from './ocean.js';
import { makeFoamRingTexture } from './textures.js';

const YAW = 0.55;
const SPEED = 2.05;

function makeFeatherGeometry() {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  shape.bezierCurveTo(0.075, 0.12, 0.085, 0.55, 0, 1.0);
  shape.bezierCurveTo(-0.085, 0.55, -0.075, 0.12, 0, 0);
  const geom = new THREE.ExtrudeGeometry(shape, {
    depth: 0.018,
    bevelEnabled: true,
    bevelThickness: 0.008,
    bevelSize: 0.008,
    bevelSegments: 1,
    curveSegments: 10,
  });
  geom.rotateX(Math.PI / 2);
  geom.computeVertexNormals();
  return geom;
}

function buildBoard() {
  const shape = new THREE.Shape();
  shape.moveTo(0, -1.7);
  shape.bezierCurveTo(0.28, -1.69, 0.45, -1.35, 0.48, -0.72);
  shape.bezierCurveTo(0.5, -0.12, 0.49, 0.44, 0.4, 1.02);
  shape.bezierCurveTo(0.32, 1.48, 0.14, 1.71, 0, 1.78);
  shape.bezierCurveTo(-0.14, 1.71, -0.32, 1.48, -0.4, 1.02);
  shape.bezierCurveTo(-0.49, 0.44, -0.5, -0.12, -0.48, -0.72);
  shape.bezierCurveTo(-0.45, -1.35, -0.28, -1.69, 0, -1.7);

  const geom = new THREE.ExtrudeGeometry(shape, {
    depth: 0.09,
    bevelEnabled: true,
    bevelThickness: 0.035,
    bevelSize: 0.035,
    bevelSegments: 3,
    curveSegments: 28,
  });
  geom.rotateX(Math.PI / 2);
  geom.computeBoundingBox();
  geom.translate(0, -geom.boundingBox.min.y, 0);
  geom.computeVertexNormals();

  const deckTop = geom.boundingBox.max.y - geom.boundingBox.min.y;

  const boardMat = new THREE.MeshPhysicalMaterial({
    color: 0xf7f0dd,
    roughness: 0.26,
    metalness: 0.04,
    clearcoat: 0.55,
    clearcoatRoughness: 0.28,
  });
  const board = new THREE.Mesh(geom, boardMat);
  board.castShadow = true;
  board.receiveShadow = true;

  // Coral racing stripe, tapered toward the nose.
  const stripeShape = new THREE.Shape();
  stripeShape.moveTo(-0.09, -1.28);
  stripeShape.bezierCurveTo(0.09, -1.28, 0.07, 0.25, 0.045, 1.05);
  stripeShape.bezierCurveTo(0.03, 1.4, 0.012, 1.6, 0, 1.64);
  stripeShape.bezierCurveTo(-0.012, 1.6, -0.03, 1.4, -0.045, 1.05);
  stripeShape.bezierCurveTo(-0.07, 0.25, -0.09, -1.28, -0.09, -1.28);
  const stripeGeom = new THREE.ShapeGeometry(stripeShape, 24);
  stripeGeom.rotateX(-Math.PI / 2);
  stripeGeom.rotateY(Math.PI);
  const stripe = new THREE.Mesh(
    stripeGeom,
    new THREE.MeshPhysicalMaterial({
      color: 0xff6b58,
      roughness: 0.35,
      clearcoat: 0.4,
    })
  );
  stripe.position.y = deckTop + 0.002;
  board.add(stripe);

  // Two thin teal pinstripes flanking the stripe.
  for (const side of [-1, 1]) {
    const pin = new THREE.Mesh(
      new THREE.PlaneGeometry(0.014, 2.55),
      new THREE.MeshBasicMaterial({ color: 0x25b7a8 })
    );
    pin.rotation.x = -Math.PI / 2;
    pin.position.set(side * 0.135, deckTop + 0.003, 0.05);
    board.add(pin);
  }

  // A small fin beneath the tail.
  const finShape = new THREE.Shape();
  finShape.moveTo(0, 0);
  finShape.lineTo(0, -0.36);
  finShape.quadraticCurveTo(0.24, -0.3, 0.44, -0.02);
  finShape.lineTo(0, 0);
  const finGeom = new THREE.ExtrudeGeometry(finShape, {
    depth: 0.026,
    bevelEnabled: false,
    curveSegments: 10,
  });
  finGeom.rotateY(Math.PI / 2);
  const fin = new THREE.Mesh(
    finGeom,
    new THREE.MeshPhysicalMaterial({ color: 0x1fa99d, roughness: 0.3, clearcoat: 0.5 })
  );
  fin.position.set(-0.013, 0.07, -0.98);
  board.add(fin);

  // Foam collar hugging the waterline.
  const foam = new THREE.Mesh(
    new THREE.PlaneGeometry(2.5, 4.3),
    new THREE.MeshBasicMaterial({
      map: makeFoamRingTexture(),
      transparent: true,
      opacity: 0.58,
      depthWrite: false,
      side: THREE.DoubleSide,
    })
  );
  foam.rotation.x = -Math.PI / 2;
  foam.position.y = 0.055;
  foam.renderOrder = 2;
  board.add(foam);

  return { board, deckTop };
}

function buildPelican() {
  const root = new THREE.Group();
  const featherGeom = makeFeatherGeometry();

  const matFeather = new THREE.MeshStandardMaterial({
    color: 0xfff6e6,
    roughness: 0.88,
    metalness: 0.0,
  });
  const matFeatherShade = new THREE.MeshStandardMaterial({
    color: 0xf0dfc7,
    roughness: 0.9,
  });
  const matBlack = new THREE.MeshStandardMaterial({
    color: 0x2e303a,
    roughness: 0.75,
  });
  const matBeak = new THREE.MeshStandardMaterial({
    color: 0xffa72d,
    roughness: 0.4,
    metalness: 0.03,
  });
  const matBeakDark = new THREE.MeshStandardMaterial({
    color: 0xd97c1a,
    roughness: 0.45,
  });
  const matPouch = new THREE.MeshStandardMaterial({
    color: 0xffc35e,
    roughness: 0.58,
  });
  const matEyeWhite = new THREE.MeshStandardMaterial({
    color: 0xfff9ee,
    roughness: 0.3,
  });
  const matPupil = new THREE.MeshStandardMaterial({
    color: 0x0c0d12,
    roughness: 0.12,
    metalness: 0.1,
  });
  const matHighlight = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const matFeet = new THREE.MeshStandardMaterial({
    color: 0xff9440,
    roughness: 0.6,
  });

  const cast = (obj) => {
    obj.traverse((o) => {
      if (o.isMesh) o.castShadow = true;
    });
    return obj;
  };

  // Body.
  const body = new THREE.Mesh(new THREE.SphereGeometry(1, 32, 24), matFeather);
  body.scale.set(0.37, 0.47, 0.52);
  body.position.set(0, 0.98, -0.02);
  body.rotation.x = 0.1;
  root.add(body);

  const chest = new THREE.Mesh(new THREE.SphereGeometry(1, 24, 18), matFeather);
  chest.scale.set(0.3, 0.36, 0.3);
  chest.position.set(0, 1.02, 0.22);
  root.add(chest);

  // Neck.
  const neckCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0, 1.2, 0.07),
    new THREE.Vector3(0, 1.36, 0.13),
    new THREE.Vector3(0, 1.52, 0.17),
    new THREE.Vector3(0, 1.68, 0.2),
    new THREE.Vector3(0, 1.8, 0.21),
  ]);
  const neck = new THREE.Mesh(new THREE.TubeGeometry(neckCurve, 30, 0.105, 14, false), matFeather);
  root.add(neck);

  // Head group, pivoted where the neck meets the skull.
  const head = new THREE.Group();
  head.position.set(0, 1.82, 0.2);
  root.add(head);

  const skull = new THREE.Mesh(new THREE.SphereGeometry(1, 32, 24), matFeather);
  skull.scale.set(0.225, 0.215, 0.245);
  skull.position.set(0, 0.04, 0.06);
  head.add(skull);

  // Crest feathers at the back of the head.
  for (let i = 0; i < 3; i++) {
    const crest = new THREE.Mesh(featherGeom, matFeatherShade);
    crest.scale.set(0.7 - i * 0.08, 1, 0.2 - i * 0.015);
    crest.position.set((i - 1) * 0.055, 0.17, -0.1 - i * 0.015);
    crest.rotation.set(-0.95 - i * 0.12, 0, (i - 1) * 0.18);
    head.add(crest);
  }

  // Beak and pouch.
  const beak = new THREE.Group();
  beak.position.set(0, 0.0, 0.22);
  beak.rotation.x = 0.15;
  head.add(beak);

  const mandibleGeom = new THREE.CylinderGeometry(0.034, 0.088, 0.95, 12, 1, false);
  mandibleGeom.rotateX(Math.PI / 2);
  const mandible = new THREE.Mesh(mandibleGeom, matBeak);
  mandible.scale.set(1.38, 0.56, 1);
  mandible.position.set(0, -0.012, 0.475);
  beak.add(mandible);

  const hook = new THREE.Mesh(new THREE.SphereGeometry(0.045, 14, 10), matBeakDark);
  hook.scale.set(0.9, 0.8, 1.1);
  hook.position.set(0, -0.065, 0.955);
  beak.add(hook);

  const pouch = new THREE.Mesh(new THREE.SphereGeometry(1, 28, 20), matPouch);
  pouch.scale.set(0.135, 0.17, 0.43);
  pouch.position.set(0, -0.155, 0.47);
  pouch.rotation.x = 0.06;
  beak.add(pouch);

  const pouchBase = new THREE.Mesh(new THREE.SphereGeometry(1, 20, 14), matPouch);
  pouchBase.scale.set(0.16, 0.13, 0.2);
  pouchBase.position.set(0, -0.1, 0.16);
  beak.add(pouchBase);

  const jawCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0, -0.03, 0.02),
    new THREE.Vector3(0, -0.075, 0.42),
    new THREE.Vector3(0, -0.07, 0.78),
    new THREE.Vector3(0, -0.06, 0.93),
  ]);
  const jawLine = new THREE.Mesh(
    new THREE.TubeGeometry(jawCurve, 20, 0.012, 8, false),
    matBeakDark
  );
  beak.add(jawLine);

  // Eyes.
  const eyeGroups = [];
  for (const side of [-1, 1]) {
    const eye = new THREE.Group();
    eye.position.set(side * 0.195, 0.065, 0.145);
    head.add(eye);

    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.062, 0.012, 8, 22), matBeak);
    ring.rotation.y = Math.PI / 2;
    ring.position.x = side * 0.012;
    eye.add(ring);

    const sclera = new THREE.Mesh(new THREE.SphereGeometry(0.058, 20, 14), matEyeWhite);
    sclera.scale.set(0.62, 1, 1);
    eye.add(sclera);

    const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.033, 16, 12), matPupil);
    pupil.position.x = side * 0.03;
    pupil.scale.set(0.72, 1, 1);
    eye.add(pupil);

    const glint = new THREE.Mesh(new THREE.SphereGeometry(0.011, 8, 6), matHighlight);
    glint.position.set(side * 0.047, 0.017, 0.017);
    eye.add(glint);

    eyeGroups.push({ eye, side });
  }

  // Wings.
  const wings = [];
  for (const side of [-1, 1]) {
    const wing = new THREE.Group();
    wing.position.set(side * 0.29, 1.16, 0.0);
    root.add(wing);

    const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.11, 18, 14), matFeather);
    wing.add(shoulder);

    const arm = new THREE.Mesh(new THREE.CapsuleGeometry(0.078, 0.38, 6, 12), matFeatherShade);
    arm.rotation.z = -side * Math.PI / 2;
    arm.position.x = side * 0.23;
    wing.add(arm);

    const hand = new THREE.Group();
    hand.position.x = side * 0.46;
    wing.add(hand);

    const featherLengths = [0.62, 0.76, 0.88, 0.94, 0.9, 0.8, 0.68];
    const feathers = [];
    for (let i = 0; i < featherLengths.length; i++) {
      const g = new THREE.Group();
      const fan = -0.22 + (i / (featherLengths.length - 1)) * 0.95;
      const droop = 0.06 + i * 0.035;
      g.rotation.order = 'YZX';
      g.rotation.y = side * (Math.PI / 2 + fan);
      g.rotation.z = -side * droop;
      g.position.y = 0.02 * i;

      const primary = i >= 4;
      const feather = new THREE.Mesh(featherGeom, primary ? matBlack : matFeather);
      feather.scale.set(primary ? 0.95 : 1.05, 1, featherLengths[i]);
      feather.castShadow = true;
      g.add(feather);
      hand.add(g);
      feathers.push({ g, baseFan: fan, baseDroop: droop, side, i });
    }

    // Shorter covert feathers layered over the base of the primaries.
    for (let i = 0; i < 4; i++) {
      const g = new THREE.Group();
      const fan = -0.05 + i * 0.2;
      g.rotation.order = 'YZX';
      g.rotation.y = side * (Math.PI / 2 + fan);
      g.rotation.z = -side * (0.16 + i * 0.03);
      g.position.set(0, 0.035, 0);
      const feather = new THREE.Mesh(featherGeom, matFeatherShade);
      feather.scale.set(1.05, 1, 0.4 + i * 0.03);
      g.add(feather);
      hand.add(g);
    }

    wing.userData = { side, feathers };
    wings.push(wing);
  }

  // Tail.
  const tail = new THREE.Group();
  tail.position.set(0, 0.82, -0.42);
  tail.rotation.x = -0.25;
  root.add(tail);
  for (let i = -2; i <= 2; i++) {
    const g = new THREE.Group();
    g.rotation.y = Math.PI + i * 0.14;
    g.rotation.x = -0.12 + Math.abs(i) * 0.05;
    const feather = new THREE.Mesh(featherGeom, i === 0 ? matFeather : matFeatherShade);
    feather.scale.set(0.95, 1, 0.46 - Math.abs(i) * 0.04);
    feather.castShadow = true;
    g.add(feather);
    tail.add(g);
  }

  // Legs and webbed feet.
  for (const side of [-1, 1]) {
    const leg = new THREE.Mesh(new THREE.CapsuleGeometry(0.042, 0.26, 5, 10), matFeet);
    leg.position.set(side * 0.16, 0.37, 0.02);
    leg.rotation.x = 0.06;
    root.add(leg);

    const foot = new THREE.Mesh(new THREE.SphereGeometry(1, 18, 12), matFeet);
    foot.scale.set(0.105, 0.035, 0.17);
    foot.position.set(side * 0.18, 0.045, 0.09);
    root.add(foot);

    for (let t = -1; t <= 1; t++) {
      const toe = new THREE.Mesh(new THREE.CapsuleGeometry(0.017, 0.1, 4, 8), matFeet);
      toe.rotation.x = Math.PI / 2;
      toe.rotation.z = t * 0.18;
      toe.position.set(side * 0.18 + t * 0.045, 0.04, 0.2);
      root.add(toe);
    }
  }

  cast(root);

  return { root, body, head, beak, pouch, wings, tail, eyeGroups, chest };
}

export function createRider() {
  const group = new THREE.Group();
  group.rotation.order = 'YXZ';

  const { board, deckTop } = buildBoard();
  group.add(board);

  const pelican = buildPelican();
  pelican.root.position.y = deckTop - 0.005;
  group.add(pelican.root);

  const forward = new THREE.Vector3(Math.sin(YAW), 0, Math.cos(YAW));
  const right = new THREE.Vector3(Math.cos(YAW), 0, -Math.sin(YAW));
  const position = new THREE.Vector3(0, 0, 0);

  const bodyBaseScale = pelican.body.scale.clone();

  return {
    group,
    board,
    pelican: pelican.root,
    deckTop,
    forward,
    right,
    position,
    speed: SPEED,
    yaw: YAW,

    update(time, dt) {
      position.x += forward.x * SPEED * dt;
      position.z += forward.z * SPEED * dt;

      const wave = sampleOcean(position.x, position.z, time);
      const slopeF = wave.dx * forward.x + wave.dz * forward.z;
      const slopeR = wave.dx * right.x + wave.dz * right.z;

      const pitch = -Math.atan(slopeF) * 0.92 + Math.sin(time * 1.25) * 0.012;
      const roll = Math.atan(slopeR) * 0.92 + Math.cos(time * 1.05) * 0.01;

      group.position.set(position.x, wave.height + 0.02, position.z);
      group.rotation.y = YAW;
      group.rotation.x = pitch;
      group.rotation.z = roll;

      // The bird balances against the board, pivoting from its feet.
      pelican.root.rotation.x = -pitch * 0.68 + Math.sin(time * 1.4) * 0.017;
      pelican.root.rotation.z = -roll * 0.58 + Math.cos(time * 1.12) * 0.021;
      pelican.root.position.y = deckTop - 0.005 + Math.sin(time * 2.1) * 0.007;

      const breathe = 1 + Math.sin(time * 1.6) * 0.012;
      pelican.body.scale.set(
        bodyBaseScale.x * breathe,
        bodyBaseScale.y * (1 + Math.sin(time * 1.6) * 0.018),
        bodyBaseScale.z * breathe
      );
      pelican.chest.scale.set(0.3 * breathe, 0.36 * (1 + Math.sin(time * 1.6 + 0.4) * 0.02), 0.3 * breathe);

      // Wings make small, continuous balancing corrections.
      for (const wing of pelican.wings) {
        const side = wing.userData.side;
        const flap = Math.sin(time * 1.75 + side * 0.55) * 0.07;
        wing.rotation.z = side * (0.31 + flap);
        wing.rotation.y = side * (0.1 + Math.sin(time * 1.05 + side * 0.9) * 0.035);
        wing.rotation.x = Math.sin(time * 1.9 + side * 1.2) * 0.04;

        for (const f of wing.userData.feathers) {
          const flutter = Math.sin(time * 2.6 + f.i * 0.7 + side) * 0.018;
          f.g.rotation.z = -f.side * (f.baseDroop + flutter);
          f.g.rotation.y = f.side * (Math.PI / 2 + f.baseFan + flutter * 0.5);
        }
      }

      // Head drifts, then settles back toward the horizon.
      pelican.head.rotation.y =
        Math.sin(time * 0.31) * 0.16 + Math.sin(time * 0.13 + 1.2) * 0.07;
      pelican.head.rotation.x = Math.sin(time * 0.7) * 0.03 - 0.02;
      pelican.head.rotation.z = Math.sin(time * 0.42 + 0.8) * 0.025;

      const pouchPulse = 1 + Math.sin(time * 2.15) * 0.035;
      pelican.pouch.scale.set(0.135, 0.17 * pouchPulse, 0.43);

      pelican.tail.rotation.z = Math.sin(time * 1.15 + 0.4) * 0.06;
      pelican.tail.rotation.x = -0.25 + Math.sin(time * 0.9) * 0.03;

      // Occasional blink.
      const blinkPhase = (time + 1.4) % 4.4;
      const blink = blinkPhase < 0.16 ? Math.sin((blinkPhase / 0.16) * Math.PI) : 0;
      for (const { eye } of pelican.eyeGroups) {
        eye.scale.y = 1 - blink * 0.92;
      }
    },
  };
}

import * as THREE from 'three';
import { sampleOcean } from './ocean.js';
import { makeSprayTexture } from './textures.js';

const COUNT = 460;

const vertexShader = /* glsl */ `
uniform float uPixelRatio;
attribute float aSize;
attribute float aAlpha;
varying float vAlpha;

void main() {
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = aSize * uPixelRatio * (330.0 / max(-mv.z, 0.1));
  gl_Position = projectionMatrix * mv;
  vAlpha = aAlpha;
}
`;

const fragmentShader = /* glsl */ `
uniform sampler2D uMap;
varying float vAlpha;

void main() {
  vec4 tex = texture2D(uMap, gl_PointCoord);
  if (tex.a < 0.012) discard;
  gl_FragColor = vec4(0.93, 0.985, 1.0, tex.a * vAlpha);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createSpray() {
  const positions = new Float32Array(COUNT * 3);
  const sizes = new Float32Array(COUNT);
  const alphas = new Float32Array(COUNT);

  const vx = new Float32Array(COUNT);
  const vy = new Float32Array(COUNT);
  const vz = new Float32Array(COUNT);
  const age = new Float32Array(COUNT);
  const life = new Float32Array(COUNT);
  const size0 = new Float32Array(COUNT);
  const growth = new Float32Array(COUNT);
  const kind = new Uint8Array(COUNT);
  const alive = new Uint8Array(COUNT);

  const geometry = new THREE.BufferGeometry();
  const positionAttr = new THREE.BufferAttribute(positions, 3);
  const sizeAttr = new THREE.BufferAttribute(sizes, 1);
  const alphaAttr = new THREE.BufferAttribute(alphas, 1);
  positionAttr.setUsage(THREE.DynamicDrawUsage);
  sizeAttr.setUsage(THREE.DynamicDrawUsage);
  alphaAttr.setUsage(THREE.DynamicDrawUsage);
  geometry.setAttribute('position', positionAttr);
  geometry.setAttribute('aSize', sizeAttr);
  geometry.setAttribute('aAlpha', alphaAttr);
  geometry.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 1e6);

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uMap: { value: makeSprayTexture() },
      uPixelRatio: { value: Math.min(window.devicePixelRatio || 1, 2) },
    },
    vertexShader,
    fragmentShader,
    transparent: true,
    depthWrite: false,
  });

  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;
  points.renderOrder = 3;

  let cursor = 0;
  let sprayAccum = 0;
  let wakeAccum = 0;

  const tmpLocal = new THREE.Vector3();
  const tmpWorld = new THREE.Vector3();

  function spawn(type, origin, rider, time) {
    let index = -1;
    for (let n = 0; n < COUNT; n++) {
      const i = (cursor + n) % COUNT;
      if (!alive[i]) {
        index = i;
        cursor = (i + 1) % COUNT;
        break;
      }
    }
    if (index < 0) return;

    const i3 = index * 3;
    const f = rider.forward;
    const r = rider.right;
    const side = Math.random() < 0.5 ? -1 : 1;

    positions[i3] = origin.x;
    positions[i3 + 1] = origin.y;
    positions[i3 + 2] = origin.z;

    if (type === 0) {
      // Bow spray: a quick fan of droplets thrown up and outward.
      const lateral = (Math.random() - 0.3) * 2.0;
      vx[i] = r.x * lateral + f.x * (0.15 + Math.random() * 0.35);
      vy[i] = 0.9 + Math.random() * 2.1;
      vz[i] = r.z * lateral + f.z * (0.15 + Math.random() * 0.35);
      life[i] = 0.45 + Math.random() * 0.65;
      size0[i] = 0.12 + Math.random() * 0.22;
      growth[i] = 1.7;
      kind[i] = 0;
    } else {
      // Wake: foam dragged off the tail, then left behind on the surface.
      const lateral = (Math.random() - 0.5) * 1.1;
      const back = 0.35 + Math.random() * 1.1;
      vx[i] = -f.x * back + r.x * lateral;
      vy[i] = 0.15 + Math.random() * 0.3;
      vz[i] = -f.z * back + r.z * lateral;
      life[i] = 1.2 + Math.random() * 1.3;
      size0[i] = 0.07 + Math.random() * 0.14;
      growth[i] = 2.3;
      kind[i] = 1;
    }

    age[i] = 0;
    alphas[i] = 0;
    sizes[i] = size0[i];
    alive[i] = 1;
  }

  return {
    points,
    update(dt, time, rider) {
      rider.group.updateMatrixWorld(true);

      sprayAccum += dt * 92;
      wakeAccum += dt * 155;

      while (sprayAccum >= 1) {
        sprayAccum -= 1;
        tmpLocal.set(
          (Math.random() - 0.5) * 0.5,
          0.05 + Math.random() * 0.12,
          1.2 + Math.random() * 0.4
        );
        tmpWorld.copy(tmpLocal).applyMatrix4(rider.group.matrixWorld);
        spawn(0, tmpWorld, rider, time);
      }

      while (wakeAccum >= 1) {
        wakeAccum -= 1;
        tmpLocal.set(
          (Math.random() - 0.5) * 0.65,
          0.05,
          -1.35 - Math.random() * 0.35
        );
        tmpWorld.copy(tmpLocal).applyMatrix4(rider.group.matrixWorld);
        spawn(1, tmpWorld, rider, time);
      }

      for (let i = 0; i < COUNT; i++) {
        if (!alive[i]) {
          alphas[i] = 0;
          continue;
        }

        age[i] += dt;
        if (age[i] >= life[i]) {
          alive[i] = 0;
          alphas[i] = 0;
          continue;
        }

        const i3 = i * 3;
        if (kind[i] === 0) {
          vy[i] -= 5.4 * dt;
          positions[i3] += vx[i] * dt;
          positions[i3 + 1] += vy[i] * dt;
          positions[i3 + 2] += vz[i] * dt;

          const surface = sampleOcean(positions[i3], positions[i3 + 2], time).height;
          if (positions[i3 + 1] < surface + 0.02) {
            positions[i3 + 1] = surface + 0.02;
            vy[i] = 0;
            vx[i] *= 0.92;
            vz[i] *= 0.92;
            age[i] += dt * 2.4;
          }
        } else {
          positions[i3] += vx[i] * dt;
          positions[i3 + 2] += vz[i] * dt;
          const surface = sampleOcean(positions[i3], positions[i3 + 2], time).height;
          positions[i3 + 1] = surface + 0.035;
          vx[i] *= 1 - 1.1 * dt;
          vz[i] *= 1 - 1.1 * dt;
        }

        const t = age[i] / life[i];
        const fadeIn = Math.min(age[i] / 0.09, 1);
        const fadeOut = 1 - t * t;
        alphas[i] = fadeIn * fadeOut * 0.9;
        sizes[i] = size0[i] * (1 + growth[i] * t);
      }

      positionAttr.needsUpdate = true;
      sizeAttr.needsUpdate = true;
      alphaAttr.needsUpdate = true;
    },
  };
}

import * as THREE from 'three';
import { createOcean } from './ocean.js';
import { createSky, SUN_DIR } from './sky.js';
import { createRider } from './pelican.js';
import { createSpray } from './particles.js';

const canvas = document.getElementById('scene');

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  powerPreference: 'high-performance',
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.06;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0xf3bf96);

const camera = new THREE.PerspectiveCamera(
  42,
  window.innerWidth / window.innerHeight,
  0.1,
  3000
);

// ---------------------------------------------------------------------------
// Light: a warm key from the camera side, a hot rim from the setting sun.
// ---------------------------------------------------------------------------

const keyLight = new THREE.DirectionalLight(0xffd7b4, 2.4);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.camera.near = 0.5;
keyLight.shadow.camera.far = 40;
keyLight.shadow.camera.left = -6;
keyLight.shadow.camera.right = 6;
keyLight.shadow.camera.top = 7;
keyLight.shadow.camera.bottom = -5;
keyLight.shadow.bias = -0.0004;
keyLight.shadow.normalBias = 0.018;
scene.add(keyLight);
scene.add(keyLight.target);

const rimLight = new THREE.DirectionalLight(0xffb26e, 2.8);
scene.add(rimLight);
scene.add(rimLight.target);

const fillLight = new THREE.DirectionalLight(0x9fd6ff, 0.55);
fillLight.position.set(-8, 4, 6);
scene.add(fillLight);

const hemi = new THREE.HemisphereLight(0x9ed6ff, 0x16454f, 1.05);
scene.add(hemi);

scene.add(new THREE.AmbientLight(0xffe1c4, 0.14));

// ---------------------------------------------------------------------------
// World.
// ---------------------------------------------------------------------------

const ocean = createOcean();
ocean.uniforms.uSunDir.value.copy(SUN_DIR);
scene.add(ocean.mesh);

const sky = createSky();
scene.add(sky.group);

const rider = createRider();
scene.add(rider.group);

const spray = createSpray();
scene.add(spray.points);

// ---------------------------------------------------------------------------
// Camera path: a slow, breathing orbit just ahead of the board.
// ---------------------------------------------------------------------------

const orbitAngle = (time) => 0.72 + Math.sin(time * 0.052) * 0.18;
const cameraRadius = (time) => 8.5 + Math.sin(time * 0.031) * 0.4;
const cameraHeight = (time) => 2.62 + Math.sin(time * 0.068) * 0.14;

const camOffset = new THREE.Vector3();
const desiredCam = new THREE.Vector3();
const lookTarget = new THREE.Vector3();
const desiredLook = new THREE.Vector3();
const axisY = new THREE.Vector3(0, 1, 0);

function placeCamera(time, dt, snap = false) {
  const a = orbitAngle(time);
  const r = cameraRadius(time);
  camOffset.set(Math.sin(a) * r, 0, Math.cos(a) * r);
  camOffset.applyAxisAngle(axisY, rider.yaw);

  desiredCam.copy(rider.position).add(camOffset);
  desiredCam.y = rider.group.position.y + cameraHeight(time);

  desiredLook.copy(rider.position);
  desiredLook.y = rider.group.position.y + 1.42;
  desiredLook.x += rider.forward.x * 0.15;
  desiredLook.z += rider.forward.z * 0.15;

  if (snap) {
    camera.position.copy(desiredCam);
    lookTarget.copy(desiredLook);
  } else {
    camera.position.lerp(desiredCam, 1 - Math.exp(-dt * 2.6));
    lookTarget.lerp(desiredLook, 1 - Math.exp(-dt * 4.2));
  }
  camera.lookAt(lookTarget);
}

// ---------------------------------------------------------------------------
// Animation loop.
// ---------------------------------------------------------------------------

const clock = new THREE.Clock();
let time = 0;
let started = false;

placeCamera(0, 0, true);

function animate() {
  requestAnimationFrame(animate);

  const dt = Math.min(clock.getDelta(), 0.05);
  time += dt;

  rider.update(time, dt);
  placeCamera(time, dt);

  ocean.update(time, rider.position);
  sky.update(time, camera);

  // Keep the shadow rig travelling with the bird.
  keyLight.position.set(
    rider.position.x + 7.5,
    rider.group.position.y + 11,
    rider.position.z + 8
  );
  keyLight.target.position.set(rider.position.x, rider.group.position.y + 0.8, rider.position.z);
  keyLight.target.updateMatrixWorld();

  rimLight.position.set(
    rider.position.x + SUN_DIR.x * 30,
    rider.group.position.y + SUN_DIR.y * 30 + 4,
    rider.position.z + SUN_DIR.z * 30
  );
  rimLight.target.position.set(rider.position.x, rider.group.position.y + 1, rider.position.z);
  rimLight.target.updateMatrixWorld();

  spray.update(dt, time, rider);

  renderer.render(scene, camera);

  if (!started) {
    started = true;
    const fade = document.getElementById('fade');
    if (fade) {
      requestAnimationFrame(() => {
        fade.style.opacity = '0';
      });
    }
  }
}

animate();

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
});

