const browser = await puppeteer.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless:true, args:['--no-sandbox','--enable-unsafe-swiftshader','--use-angle=swiftshader']});
const page = await browser.newPage();
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:8898/index.html', {waitUntil:'networkidle0', timeout:60000});
await new Promise(r=>setTimeout(r,4000));
const data = await page.evaluate(() => {
  const d = window.__debug;
  const rider = d.rider;
  const ocean = d.ocean;
  const group = rider.group;
  const board = rider.board;
  board.updateWorldMatrix(true,true);
  return {
    groupPos: group.position.toArray(),
    riderPos: rider.position.toArray(),
    groupRot: [group.rotation.x, group.rotation.y, group.rotation.z],
    oceanUniformTime: ocean.uniforms.uTime.value,
    oceanOffset: ocean.uniforms.uOffset.value.toArray(),
    boardWorldTranslate: board.matrixWorld.elements.slice(12,15),
    boardGeomBBox: board.geometry.boundingBox ? [board.geometry.boundingBox.min.toArray(), board.geometry.boundingBox.max.toArray()] : null,
    deckTop: rider.deckTop,
    sceneChildrenCount: d.scene.children.length,
  };
});
console.log(JSON.stringify(data,null,2));
await browser.close();
" 2>&1 | tail -40

python3 - <<'PY'
from pathlib import Path
p=Path('main.js'); s=p.read_text()
s=s.replace("\nwindow.__debug = { rider, ocean, camera, scene };", "")
s=s.replace("  const a = orbitAngle(time);\n  const r = cameraRadius(time);\n  camOffset.set(Math.sin(a) * r, 0, Math.cos(a) * r);", "  const a = orbitAngle(time);\n  const fit = Math.max(1, 0.72 / camera.aspect);\n  const r = cameraRadius(time) * fit;\n  camOffset.set(Math.sin(a) * r, 0, Math.cos(a) * r);")
p.write_text(s)

p=Path('sky.js'); s=p.read_text()
old="""    sprite.material.rotation = (rand() - 0.5) * 0.35;
    group.add(sprite);
  }
"""
new="""    sprite.material.rotation = (rand() - 0.5) * 0.35;
    sprite.userData.base = sprite.position.clone();
    sprite.userData.phase = rand() * Math.PI * 2;
    sprite.userData.drift = 5 + rand() * 9;
    group.add(sprite);
  }

  const clouds = group.children.filter((child) => child.isSprite && child.userData.base);
"""
if old not in s: raise SystemExit('cloud block not found')
s=s.replace(old,new)
old2="""      for (const bird of birds) {
        const { rightPivot, leftPivot, flapSpeed, phase } = bird.userData;
        const flap = Math.sin(time * flapSpeed + phase) * 0.55;
        rightPivot.rotation.z = flap;
        leftPivot.rotation.z = -flap;
        bird.position.x += Math.sin(time * 0.05 + phase) * 0.0015;
      }
"""
new2="""      for (const cloud of clouds) {
        const { base, phase, drift } = cloud.userData;
        cloud.position.x = base.x + Math.sin(time * 0.008 + phase) * drift;
        cloud.position.z = base.z + Math.cos(time * 0.006 + phase) * drift * 0.4;
      }
      for (const bird of birds) {
        const { rightPivot, leftPivot, flapSpeed, phase } = bird.userData;
        const flap = Math.sin(time * flapSpeed + phase) * 0.55;
        rightPivot.rotation.z = flap;
        leftPivot.rotation.z = -flap;
        bird.position.x += Math.sin(time * 0.05 + phase) * 0.0015;
      }
"""
if old2 not in s: raise SystemExit('bird block not found')
s=s.replace(old2,new2)
p.write_text(s)
